\label{lem:two-block-jacquet}
Let $\rho$ be a unitary supercuspidal representation of $G_d$, put
$s=s(\rho)$, and let $1\le a\le m-1$. Then
\begin{equation}\label{eq:general-two-block-jacquet}
\begin{split}
 &r_{(ad,(m-a)d),(md)}\bigl(\delta_m(\rho)\bigr)\\
 &\qquad=
 \nu^{s(m-a)/2}\delta_a(\rho)
 \otimes
 \nu^{-sa/2}\delta_{m-a}(\rho).
\end{split}
\end{equation}
More generally, a Jacquet module of $\delta_m(\rho)$ is zero unless every
block size in the chosen Levi is divisible by $d$.

\label{lem:block-temp}
For every $\rho\in\mathcal D_r$ and $m\geq1$, the representation
$\mathcal B_m(\rho)$ is irreducible and tempered.

\label{thm:rank5}
Let $\pi$ be an irreducible tempered representation of $G_5$. Then
\[
 \operatorname{Hom}_{H_5}(\pi,\mathbb C)\neq0
\]
if and only if, up to permutation of the inducing factors, $\pi$ belongs to
one of the following families:
\begin{enumerate}[label=\textup{(\arabic*)}]
\item $\rho_5$, where $\rho_5\in\mathcal D_5$;
\item $\rho_3\times\chi_1\times\chi_2$, where
 $\rho_3\in\mathcal D_3$ and $\chi_1,\chi_2\in\mathcal D_1$;
\item $\chi_1\times\chi_2\times\chi_3\times\chi_4\times\chi_5$, where
 $\chi_i\in\mathcal D_1$;
\item $\mathcal B_1(\chi)\times\chi_1\times\chi_2$, where
 $\chi,\chi_1,\chi_2\in\mathcal D_1$;
\item $\mathcal B_2(\chi)=\delta_3(\chi)\times\delta_2(\chi)$, where
 $\chi\in\mathcal D_1$.
\end{enumerate}
